/**
 * 初始化 ECharts 图表
 * @param {string} elementId - DOM 元素 ID
 * @param {object} option - ECharts 配置项
 * @param {boolean} autoResize - 是否自动适配容器大小，默认 true
 * @returns {object|null} ECharts 实例，初始化失败返回 null
 */
const initChart = (elementId, option, autoResize = true) => {
    // 1. 参数校验
    if (!elementId || typeof elementId !== 'string') {
        console.error('[initChart] 参数错误: elementId 必须是非空字符串');
        return null;
    }
    
    // 2. 获取 DOM 元素
    const dom = document.getElementById(elementId);
    if (!dom) {
        console.error(`[initChart] DOM 元素不存在: #${elementId}`);
        return null;
    }
    
    // 3. 检查是否已存在实例（避免重复初始化）
    let chart = echarts.getInstanceByDom(dom);
    if (chart) {
        // 已存在实例，直接更新配置
        chart.setOption(option, true); // true = 完全替换
        return chart;
    }
    
    // 4. 初始化新实例
    try {
        chart = echarts.init(dom);
        chart.setOption(option);
        
        // 5. 自动适配容器大小变化（窗口 resize）
        if (autoResize) {
            window.addEventListener('resize', () => {
                chart.resize();
            });
        }
        
        return chart;
    } catch (error) {
        console.error(`[initChart] 初始化失败:`, error);
        return null;
    }
};
