// 工具函数
const createDaysArray = (days) => {
    const length = days == 30 ? 30 : 31
    return Array.from({ length }, (_, i) => ({
        time: i + 1,
        mun: 0
    }))
}
const processChartData = async (ajaxCall, daysList, dataKey, isDot = false) => {
    try {
        const res = await ajaxCall
        const xlist = []
        const ylist = []

        daysList.forEach(item => {
            const matchedItem = res.data.find(item1 => 
                parseInt(item1.date.split('-')[2]) === item.time
            )
            if (matchedItem) {
                item.mun = isDot ? userTime.isDot(parseInt(matchedItem[dataKey])) : matchedItem[dataKey]
            }
        })

        daysList.forEach(item => {
            xlist.push(item.time)
            ylist.push(item.mun)
        })

        return { xlist, ylist }
    } catch (error) {
        console.error('处理图表数据失败:', error)
        return { xlist: [], ylist: [] }
    }
}

const createTooltipFormatter = (seriesName, typeValue, activeType = 'activeName') => {
    return (params) => {
        const n = typeValue === 1 ? 0 : -1
        const start = getMonth("s", n)
        const dateArray = start.split("-")
        const date = new Date(dateArray[0], parseInt(dateArray[1]) - 1, params[0].name)
        const weekDay = ["星期天", "星期一", "星期二", "星期三", "星期四", "星期五", "星期六"]
        const week = weekDay[date.getDay()]
        const timestr = `${dateArray[0]}年${Number(dateArray[1])}月${params[0].name}日(${week})`
        const numData = params[0].value ? params[0].value : 0
        
        return `
            <div style="background:rgba(255,255,255,1);margin-top:20px;border:1px solid rgba(238,238,238,1);box-shadow:0px 0px 10px 0px rgba(51,51,51,0.2);border-radius:10px;color:rgba(102,102,102,1);font-weight:400;font-family:MicrosoftYaHei;font-size:14px;padding:20px;">
                <div>${timestr}</div>
                <div>${seriesName}:${numData}</div>
            </div>
        `
    }
}

const axisLabelFormatter = (value) => {
